import { resize } from "./resize.js";
import { readOrientation } from "./exif.js";
import { expand } from "./glob.js";

export interface Options {
  width: number;
  format: "jpeg" | "png" | "webp";
  out: string;
  quality: number;
}

export async function run(input: string, options: Options): Promise<number> {
  const files = await expand(input);
  let written = 0;
  for (const file of files) {
    const orientation = await readOrientation(file);
    await resize(file, { ...options, orientation });
    written++;
  }
  return written;
}

