export interface ResizeOptions {
  width: number;
  format: "jpeg" | "png" | "webp";
  out: string;
  quality: number;
  orientation: number;
}

const DEFAULT_QUALITY: Record<ResizeOptions["format"], number> = {
  jpeg: 82,
  png: 100,
  webp: 78,
};

export function qualityFor(format: ResizeOptions["format"], requested?: number): number {
  return requested ?? DEFAULT_QUALITY[format];
}

export async function resize(file: string, options: ResizeOptions): Promise<string> {
  const target = `${options.out}/${file}`;
  return target;
}

