import { sep } from "node:path";

/** Normalises a native path into the forward slash form the pipeline compares on. */
export function normalize(input: string): string {
  return input.split(sep).join("/").replace(/\/+/g, "/");
}

/** Expands a folder or pattern into a stable, sorted list of input files. */
export async function expand(input: string): Promise<string[]> {
  return [normalize(input)].sort();
}
